public abstract class CheckoutFlow {
    public async Task<Receipt> RunAsync(Cart cart, CancellationToken ct) {   // skeleton
        var priced = await PriceAsync(cart, ct);      // required step
        var paid = await PayAsync(priced, ct);        // required step
        await OnPaidAsync(paid, ct);                  // hook: empty default
        return BuildReceipt(paid);                    // required step
    }
    protected abstract Task<Priced> PriceAsync(Cart cart, CancellationToken ct);
    protected abstract Task<Paid> PayAsync(Priced priced, CancellationToken ct);
    protected virtual Task OnPaidAsync(Paid paid, CancellationToken ct) => Task.CompletedTask;
    protected abstract Receipt BuildReceipt(Paid paid);
}

